def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Compute scores to track relative performance
    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                my_score += 0
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
                opp_score += 0
            else:
                my_score += 1
                opp_score += 1

    score_diff = my_score - opp_score

    # Statistics
    opp_def_count = sum(1 for _, b in history if b == 'D')
    recent_window = min(10, n)
    recent_op_defs = sum(1 for _, b in history[-recent_window:] if b == 'D')
    recent_opp_coop_rate = (recent_window - recent_op_defs) / recent_window

    # Streaks
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            c_streak += 1
        else:
            break

    rounds_left = 100 - n

    # Endgame Logic
    if rounds_left <= 2:
        # If opponent is very cooperative or has been consistently nice, defect to grab max points.
        # If they have defected recently, they might be retaliating, so D is safer or equal payoff-wise against D.
        # Actually, against C, D gives 5 vs 3. Against D, D gives 1 vs 0 (if we played C). 
        # So D is dominant in last round.
        if opp_last == 'C' and recent_opp_coop_rate > 0.6:
             return 'D'
        if rounds_left == 1:
             return 'D'
        # Round 99: Defect if likely to get exploited next round? No, game ends.
        # Standard end-game defection against cooperators.
        return 'D' if opp_last == 'C' or opp_def_count < n // 2 else 'D'

    if rounds_left <= 5:
        if recent_opp_coop_rate >= 0.8 and opp_last == 'C':
            return 'D'
        if opp_last == 'D':
            return 'D'

    # Early Game Stability
    if n < 4:
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Opponent Type Detection & Response

    # 1. Hard Defector / Aggressive
    if recent_opp_coop_rate < 0.3:
        # If we are significantly behind, maybe try one forgiveness move to reset?
        if score_diff < -10 and opp_last == 'C' and rng.random() < 0.1:
            return 'C'
        return 'D'

    # 2. Mixed / Unpredictable / Tit-for-Tat-like
    # Focus on reciprocity with slight noise tolerance

    if opp_last == 'D':
        # Forgiveness conditions:
        # A) Isolated defection in a mostly cooperative environment
        # B) We are far ahead (risk management)

        is_isolated = (opp_d_streak == 1 and recent_opp_coop_rate > 0.5)
        high_forgiveness_prob = 0.0

        if is_isolated:
            high_forgiveness_prob = 0.3
        elif recent_opp_coop_rate > 0.7 and opp_d_streak <= 2:
            high_forgiveness_prob = 0.15
        elif score_diff > 10:
            high_forgiveness_prob = 0.2

        if rng.random() < high_forgiveness_prob:
            return 'C'

        # Retaliate otherwise
        return 'D'

    else: # opp_last == 'C'
        # Opportunity to exploit?
        # If opponent is highly consistent cooperator, occasional defection yields 5 vs 3.
        # But risks triggering retaliation loop.

        # Exploit only if:
        # 1. They have cooperated many times in a row
        # 2. We are not too far behind (or we are leading, safe to take risk)
        # 3. Not near endgame where logic handles it

        if c_streak >= 5 and recent_opp_coop_rate > 0.9:
            if rng.random() < 0.1:
                return 'D'

        # Otherwise cooperate
        return 'C'
